// HubServiceHandler is an implementation of the ghhud.v1.HubService service.
type HubServiceHandler interface {
	// GetSnapshot returns the hub's current state.
	GetSnapshot(context.Context, *connect.Request[v1.GetSnapshotRequest]) (*connect.Response[v1.GetSnapshotResponse], error)
	// Subscribe streams the current snapshot, then every change, and the
	// events (notices and alerts) that happen meanwhile. A slow reader
	// skips intermediate snapshots but always gets the newest.
	Subscribe(context.Context, *connect.Request[v1.SubscribeRequest], *connect.ServerStream[v1.SubscribeResponse]) error
	// Refresh asks for a refresh now; it coalesces with work in flight.
	Refresh(context.Context, *connect.Request[v1.RefreshRequest]) (*connect.Response[v1.RefreshResponse], error)
	// Dispatch. These fail with FAILED_PRECONDITION when dispatch is off,
	// and the hub refuses changes while another gh-hud owns dispatch.
	MenuChoices(context.Context, *connect.Request[v1.MenuChoicesRequest]) (*connect.Response[v1.MenuChoicesResponse], error)
	Dispatch(context.Context, *connect.Request[v1.DispatchRequest]) (*connect.Response[v1.DispatchResponse], error)
	// ItemChoices looks up an issue or PR you name, in the latest refresh
	// or else on GitHub, and lists every task that fits it (MenuChoices
	// lists only those its state calls for, and only for refreshed items).
	// Dispatch then takes the item's URL. INVALID_ARGUMENT when ref isn't
	// an issue or PR.
	ItemChoices(context.Context, *connect.Request[v1.ItemChoicesRequest]) (*connect.Response[v1.ItemChoicesResponse], error)
	Reinspect(context.Context, *connect.Request[v1.ReinspectRequest]) (*connect.Response[v1.ReinspectResponse], error)
	// PruneBranches finds the dispatch checkouts' branches whose PR is
	// merged or closed, and your forks' (gh-hud branches); with apply it
	// deletes them and fast-forwards the forks' default branches.
	PruneBranches(context.Context, *connect.Request[v1.PruneBranchesRequest]) (*connect.Response[v1.PruneBranchesResponse], error)
	// Your queue of agent tasks.
	QueueChoices(context.Context, *connect.Request[v1.QueueChoicesRequest]) (*connect.Response[v1.QueueChoicesResponse], error)
	Enqueue(context.Context, *connect.Request[v1.EnqueueRequest]) (*connect.Response[v1.EnqueueResponse], error)
	Unqueue(context.Context, *connect.Request[v1.UnqueueRequest]) (*connect.Response[v1.UnqueueResponse], error)
	MoveQueued(context.Context, *connect.Request[v1.MoveQueuedRequest]) (*connect.Response[v1.MoveQueuedResponse], error)
	// Supervisor proposals (Snapshot.cases), by proposal id.
	ApproveProposal(context.Context, *connect.Request[v1.ApproveProposalRequest]) (*connect.Response[v1.ApproveProposalResponse], error)
	RejectProposal(context.Context, *connect.Request[v1.RejectProposalRequest]) (*connect.Response[v1.RejectProposalResponse], error)
	// Epics (Snapshot.epics), by ref (owner/repo#N).
	EnrollEpic(context.Context, *connect.Request[v1.EnrollEpicRequest]) (*connect.Response[v1.EnrollEpicResponse], error)
	ApproveEpic(context.Context, *connect.Request[v1.ApproveEpicRequest]) (*connect.Response[v1.ApproveEpicResponse], error)
	DropEpic(context.Context, *connect.Request[v1.DropEpicRequest]) (*connect.Response[v1.DropEpicResponse], error)
	RereadEpic(context.Context, *connect.Request[v1.RereadEpicRequest]) (*connect.Response[v1.RereadEpicResponse], error)
	// ClearEpicGate says a piece's gate holds: it no longer waits on it.
	ClearEpicGate(context.Context, *connect.Request[v1.ClearEpicGateRequest]) (*connect.Response[v1.ClearEpicGateResponse], error)
	// FinishEpic posts a finished epic's summary on it, as you, and closes
	// it as completed (gh-hud#22). Every piece must be done or dropped.
	FinishEpic(context.Context, *connect.Request[v1.FinishEpicRequest]) (*connect.Response[v1.FinishEpicResponse], error)
	// Viewers. They open a terminal window on the hub's machine.
	Watch(context.Context, *connect.Request[v1.WatchRequest]) (*connect.Response[v1.WatchResponse], error)
	WatchRun(context.Context, *connect.Request[v1.WatchRunRequest]) (*connect.Response[v1.WatchRunResponse], error)
	OpenTranscript(context.Context, *connect.Request[v1.OpenTranscriptRequest]) (*connect.Response[v1.OpenTranscriptResponse], error)
	// Viewers for apps on other devices: the content instead of a window.
	// ReadPane returns the end of a live agent's herdr pane, as Watch shows
	// it; Transcript a run's opencode session as messages. Read-only: a
	// hub that follows another gh-hud serves them too.
	ReadPane(context.Context, *connect.Request[v1.ReadPaneRequest]) (*connect.Response[v1.ReadPaneResponse], error)
	Transcript(context.Context, *connect.Request[v1.TranscriptRequest]) (*connect.Response[v1.TranscriptResponse], error)
	// FleetControl drives the GitOps rollout; FAILED_PRECONDITION when the
	// fleet is off.
	FleetControl(context.Context, *connect.Request[v1.FleetControlRequest]) (*connect.Response[v1.FleetControlResponse], error)
	// DeweyReindex starts, or cancels, a pass that reindexes the Dewey
	// vaults on a fleet machine, or on every one (#139): the ones Dewey
	// says need it (#138), or every one with force. A pass goes vault by
	// vault, skipping busy ones; its progress is FleetMachine.dewey_pass.
	// FAILED_PRECONDITION when the fleet is off; refused when
	// [dispatch] dewey_reindex is "off", a pass already runs there, or this
	// hub doesn't own dispatch.
	DeweyReindex(context.Context, *connect.Request[v1.DeweyReindexRequest]) (*connect.Response[v1.DeweyReindexResponse], error)
	// CheckoutAction starts one action on one fleet checkout from the
	// Workspaces list (#172): fast-forward it, open its learnings PRs, save
	// its leftover work to a draft PR, keep it up now, or reindex its Dewey
	// vault. It runs in the background; the outcome is the checkout's last
	// upkeep or reindex and an event. Refused when this hub doesn't own
	// dispatch, the checkout isn't a fleet checkout in the last Workspaces
	// read, or its machine's slot is taken.
	CheckoutAction(context.Context, *connect.Request[v1.CheckoutActionRequest]) (*connect.Response[v1.CheckoutActionResponse], error)
	// ToolkitRollout starts rolling a tool release out (issue #75);
	// ToolkitControl drives rollouts. FAILED_PRECONDITION when the toolkit
	// is off.
	ToolkitRollout(context.Context, *connect.Request[v1.ToolkitRolloutRequest]) (*connect.Response[v1.ToolkitRolloutResponse], error)
	ToolkitControl(context.Context, *connect.Request[v1.ToolkitControlRequest]) (*connect.Response[v1.ToolkitControlResponse], error)
}

